function icon(n,cl=''){return `<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.spark}"/></svg>`}
function mark(cl=''){return `<img class="brand-mark ${cl}" src="assets/cloudcore-mark.png" alt="" aria-hidden="true">`}
function brand(){return `<a class="brand" href="#landing" aria-label="CloudCore AI landing page">${mark()}<span><strong>CloudCore <b>AI</b></strong><small>A product of PTCL Smart Cloud</small></span></a>`}
function wave(cl=''){return `<svg class="wave ${cl}" viewBox="0 0 1400 260" preserveAspectRatio="none" aria-hidden="true">${Array.from({length:34},(_,i)=>`<path d="M-100 ${95+i*2} C210 ${-150+i*9}, 350 ${400-i*2}, 680 ${135+i} S 850 ${-40+i*6}, 1100 ${100+i*3} S1350 ${260-i*4},1500 ${55+i*3}"/>`).join('')}</svg>`}
function footer(){return `<footer class="page-footer"><span>Technology that moves Pakistan forward.</span><i></i><span>${mark('footer-mark')} A product of PTCL Smart Cloud</span></footer>`}
function landing(){return `<div class="landing"><div class="hero-backdrop"></div><header class="landing-header">${brand()}<nav aria-label="Main navigation"><a class="active" href="#landing">Home</a><a href="#solutions">Solutions</a><a href="#assistant">AI Assistant</a><a href="#documents">Resources</a><a href="#about">About</a></nav><a class="landing-search" href="#home">${icon('search')}<span>Search solutions, insights, or support...</span></a><button class="icon-button notification" aria-label="Notifications" data-action="notifications">${icon('bell')}<i></i></button><a class="sign-in" href="#home">${icon('user')}<span>Sign In</span></a></header><main><section class="hero"><div class="eyebrow">CLOUDCORE AI</div><h1>Smarter Connections<br><span>for a Stronger Tomorrow</span></h1><p>Your AI-powered partner for business solutions,<br>insights and support — from PTCL Smart Cloud.</p><div class="hero-actions"><a class="primary" href="#home">${icon('chat')} Chat with CloudCore AI ${icon('arrow')}</a><a class="explore" href="#solutions"><span>${icon('play')}</span> Explore Our Solutions</a></div><div class="hero-motto">People<br>Technology<br><b>A Brighter Pakistan</b><i></i></div><div class="signature">Connected<br><span>for a Better</span><br><em>Tomorrow</em></div></section><section class="service-strip" aria-label="Our solutions">${[['signal','Reliable Connectivity','Keep your business always on'],['cloud','Cloud & Data Solutions','Scale with confidence'],['shield','Cyber Security','A safer, stronger tomorrow'],['chip','AI-Powered Support','Instant answers. Real progress.']].map(([i,t,d])=>`<a href="#solutions" class="service-card"><span class="service-icon">${icon(i)}</span><span><strong>${t}</strong><small>${d}</small></span>${icon('chevron')}</a>`).join('')}</section><section class="impact" id="about">${wave()}<div class="impact-intro"><div class="eyebrow">POWERING PAKISTAN’S BUSINESS GROWTH</div><h2>Technology that moves<br><span>Pakistan forward.</span></h2><p>From intelligent connectivity to cloud, security and AI —<br>PTCL Smart Cloud helps organizations work smarter,<br>grow faster and build a more connected Pakistan.</p><a class="outline small" href="#solutions">Learn More ${icon('arrow')}</a></div><div class="stats">${[['users','10,000+','Business Customers'],['building','200+','Enterprise Partners'],['cloud','99.9%','Network Reliability'],['chart','A Stronger<br>Pakistan','Our Shared Purpose']].map(([i,t,d])=>`<article class="stat"><span>${icon(i)}</span><h3>${t}</h3><p>${d}</p><i></i></article>`).join('')}</div></section></main><footer class="landing-footer">${brand()}<span class="footer-credit">A product of PTCL Smart Cloud</span><div><button data-action="privacy">Privacy</button><button data-action="terms">Terms</button><a href="#assistant">Contact</a><span class="connected">A Connected Pakistan. <i></i></span></div></footer></div>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}
function route(){const r=location.hash.slice(1)||'landing';$('#app').innerHTML=(r==='landing'||r==='about')?landing():workspace(r);bind();window.scrollTo(0,0);if(r==='about')$('#about').scrollIntoView({behavior:'smooth'});}
function bind(){document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{const a=el.dataset.action;if(a==='notifications')toast('You are all caught up. No new notifications.');else if(a==='privacy')modal('<h2>Privacy by design</h2><p>Conversation history is stored in this browser. Files remain on your device unless a connected service is explicitly used.</p>');else if(a==='terms')modal('<h2>CloudCore AI terms</h2><p>This product experience demonstrates the CloudCore AI workspace. Enterprise access, data retention, and connected services are governed by your organization.</p>');else actions(a,el)});}
