function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function sidebar(r){return `<aside class="sidebar">${brand()}<button class="primary new-chat" data-action="new-chat">${icon('plus')} New Chat</button><nav aria-label="Product navigation">${navs.map(([id,i,t])=>`<a href="#${id}" class="${r===id?'selected':''}">${icon(i)}<span>${t}</span></a>`).join('')}</nav><div class="sidebar-bottom"><button data-action="settings">${icon('settings')}<span>Settings</span></button><button data-action="help">${icon('help')}<span>Help Center</span></button><a href="#landing">${icon('logout')}<span>Back to website</span></a><div class="cloud-credit">${mark('credit-mark')}<span>A product of<strong>PTCL Smart Cloud</strong></span></div></div></aside>`}
function workspace(r){if(!navs.some(n=>n[0]===r))r='home';return `<div class="workspace ${r}-workspace">${sidebar(r)}<div class="workspace-body"><header class="workspace-header"><button class="mobile-menu icon-button" data-action="menu" aria-label="Toggle navigation">${icon('menu')}</button><form class="global-search" id="search-form">${icon('search')}<input aria-label="Search CloudCore AI" placeholder="Search tools, solutions, or ask a question..."></form><div class="user-controls"><button class="icon-button notification" data-action="notifications" aria-label="Notifications">${icon('bell')}<i></i></button><button class="user-menu" data-action="profile"><span class="avatar">A</span><span><small>Welcome,</small><strong>Ali</strong></span><span class="down">&#8964;</span></button></div></header><main class="workspace-main">${wave('workspace-wave')}${r==='home'?home():r==='documents'?documents():r==='images'?images():r==='solutions'?solutions():r==='history'?history():assistant()}</main>${footer()}</div></div><input hidden type="file" id="document-input" accept=".pdf,.docx,.pptx,.xlsx,.txt,.md"><input hidden type="file" id="image-input" accept="image/png,image/jpeg,image/webp"><dialog id="dialog"><button class="dialog-close icon-button" data-action="close-dialog" aria-label="Close">${icon('close')}</button><div id="dialog-content"></div></dialog>`}
function home(){const recent=chats.slice(0,3);return `<section class="dashboard-hero"><div><div class="eyebrow">GOOD MORNING, ALI</div><h1>Your intelligent business workspace.</h1><p>Move from a question to a decision with connected AI tools, enterprise knowledge, and PTCL Smart Cloud expertise.</p><div class="dashboard-actions"><a class="primary" href="#assistant">${icon('spark')} Ask CloudCore AI</a><a class="outline" href="#solutions">Explore solutions ${icon('arrow')}</a></div></div><div class="daily-brief"><span class="brief-label">${icon('bulb')} TODAY'S BRIEF</span><strong>3 ways CloudCore AI can help</strong><ul><li>Turn a proposal into an executive summary</li><li>Review an infrastructure image for context</li><li>Compare cloud and connectivity options</li></ul></div></section><section class="workspace-kpis">${[['chat','AI conversations',chats.length,'Saved on this device'],['file','Documents reviewed',docFile?1:0,docFile?'1 file ready':'Upload your first file'],['image','Images inspected',imageURL?1:0,imageURL?'Analysis ready':'Choose an image'],['grid','Solution areas',solutionsData.length,'Across five categories']].map(([i,l,v,n])=>`<article><span class="kpi-icon">${icon(i)}</span><div><small>${l}</small><strong>${v}</strong><p>${n}</p></div></article>`).join('')}</section><section class="dashboard-grid"><div class="panel dashboard-tools"><div class="section-row"><div><span class="section-kicker">START A WORKFLOW</span><h2>What do you want to accomplish?</h2></div><span>Four focused workspaces</span></div><div class="tool-grid">${[['assistant','chat','Ask and create','Research, plan, write and make business decisions with context.'],['documents','file','Understand a document','Extract the summary, obligations, risks and next steps.'],['images','image','Inspect an image','Find objects, text, context and technical observations.'],['solutions','grid','Find the right solution','Explore and compare PTCL business capabilities.']].map(([r,i,t,d])=>`<a href="#${r}"><span class="feature-icon">${icon(i)}</span><div><h3>${t}</h3><p>${d}</p><b>Open workspace ${icon('arrow')}</b></div></a>`).join('')}</div></div><aside class="panel activity-panel"><div class="section-row"><div><span class="section-kicker">RECENT ACTIVITY</span><h2>Continue your work</h2></div><a href="#history">View all</a></div><div class="activity-list">${recent.length?recent.map(c=>`<button data-action="open-chat" data-id="${c.id}"><span class="mini-icon">${icon('chat')}</span><span><b>${esc(c.title)}</b><small>${relativeTime(c.updated)}${c.sample?'  - Guided example':''}</small></span>${icon('chevron')}</button>`).join(''):`<div class="compact-empty"><p>No recent conversations yet.</p><a href="#assistant">Start with AI Assistant</a></div>`}</div><div class="service-health"><span><i></i> Core services operational</span><small>Local workspace ready</small></div></aside></section>`}
function composer(id){return `<form class="composer" id="${id}-composer"><div><input name="prompt" aria-label="Message CloudCore AI" placeholder="${assistantMode==='Proposal Writer'?'Describe the proposal you need...':assistantMode==='Service Support'?'Describe the service issue...':'Ask CloudCore AI anything...'}" autocomplete="off" required><button type="button" class="icon-button" data-action="attach-document" aria-label="Attach a document">${icon('paperclip')}</button><button type="button" class="icon-button" data-action="attach-image" aria-label="Upload an image">${icon('image')}</button></div><button type="submit" class="send" aria-label="Send message">${icon('arrow')}</button></form>`}
function title(eyebrow,heading,sub){return `<div class="section-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${sub}</p></div><div class="heading-brand">${mark('heading-mark')}<span><b>CloudCore AI</b><small>A product of PTCL Smart Cloud</small></span></div></div>`}
function solutions(){const cats=['All','Connectivity','Cloud','Security','Workplace','AI'];const shown=solutionFilter==='All'?solutionsData:solutionsData.filter(s=>s.category===solutionFilter);return `${title('BUSINESS SOLUTIONS','Built for how your business operates.','Explore connected infrastructure, cloud, security, workplace and AI capabilities from PTCL Smart Cloud.')}<section class="solution-overview"><div class="solution-pulse"><span>${icon('spark')}</span><div><small>RECOMMENDED START</small><h2>Build a connected, secure cloud foundation</h2><p>Combine managed connectivity, local cloud and cyber security for a resilient operating model.</p></div><button class="outline" data-action="solution-detail" data-id="cloud">View recommendation ${icon('arrow')}</button></div><div class="solution-benefits"><div><b>One partner</b><span>Network, cloud and operations</span></div><div><b>Local expertise</b><span>Support across Pakistan</span></div><div><b>Designed to scale</b><span>From one workload to every site</span></div></div></section><div class="solution-toolbar"><div class="filter-pills" role="group" aria-label="Filter solutions">${cats.map(c=>`<button class="${solutionFilter===c?'active':''}" data-action="solution-filter" data-filter="${c}">${c}</button>`).join('')}</div><span>${shown.length} solutions</span></div><section class="solution-catalog">${shown.map(s=>`<article class="solution-card"><div class="solution-card-top"><span class="feature-icon">${icon(s.icon)}</span><span class="solution-category">${s.category}</span></div><h2>${s.title}</h2><p>${s.desc}</p><ul>${s.bullets.map(b=>`<li>${icon('check')}${b}</li>`).join('')}</ul><div class="solution-meta"><span><small>Best for</small><b>${s.fit}</b></span><span><small>Key value</small><b>${s.metric}</b></span></div><div class="solution-actions"><button class="primary" data-action="solution-detail" data-id="${s.id}">View solution ${icon('arrow')}</button><button class="compare-button ${solutionCompare.includes(s.id)?'selected':''}" data-action="toggle-compare" data-id="${s.id}">${solutionCompare.includes(s.id)?icon('check'):'+'} Compare</button></div></article>`).join('')}</section>${solutionCompare.length?`<div class="compare-dock"><span><b>${solutionCompare.length} selected</b><small>Compare up to 3 solutions</small></span><div>${solutionCompare.map(id=>`<button data-action="solution-detail" data-id="${id}">${solutionsData.find(s=>s.id===id).title}</button>`).join('')}</div><button class="primary" data-action="compare-solutions">Compare now ${icon('arrow')}</button></div>`:''}`}
function relativeTime(value){const d=Math.max(0,Date.now()-value),h=Math.floor(d/3600000);return h<1?'Just now':h<24?h+'h ago':Math.floor(h/24)+'d ago'}
const sampleSummary='This example document outlines PTCL’s enterprise connectivity solutions including dedicated internet, MPLS, cloud services and managed support SLAs for corporate clients. It highlights key service features, deployment options, benefits and commercial terms.';
function documentInsightContent(){if(docFile)return `<div class="analysis-state custom-file-state"><span class="summary-file">${icon('file')}</span><div><span class="state-label">FILE READY</span><h3>${esc(docFile.name)}</h3><p>Your file passed the local type and size checks. Choose an analysis action to continue when the enterprise AI service is connected.</p><div class="file-facts"><span>${(docFile.size/1048576).toFixed(2)} MB</span><span>${esc(docFile.name.split('.').pop().toUpperCase())}</span><span>Stored on this device</span></div></div></div>`;if(docTab==='Summary')return `<div class="analysis-prose"><span class="state-label">EXECUTIVE SUMMARY</span><p>${sampleSummary}</p><div class="summary-highlights"><div><b>Business objective</b><span>Modernize branch connectivity while improving visibility and resilience.</span></div><div><b>Recommended approach</b><span>Phase deployment across priority sites with managed operations and agreed service levels.</span></div><div><b>Decision required</b><span>Confirm rollout sequence, recovery targets and commercial assumptions.</span></div></div></div>`;if(docTab==='Key Points')return `<div class="insight-list">${[['01','Connectivity architecture','Dedicated internet, MPLS and SD-WAN options are mapped to different site profiles.'],['02','Cloud readiness','Workloads are grouped by data sensitivity, latency and recovery requirements.'],['03','Managed operations','Monitoring, incident ownership and escalation paths are included.'],['04','Commercial structure','Deployment, recurring services and support terms require final confirmation.']].map(([n,t,d])=>`<div><span>${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}</div>`;if(docTab==='Risks & Obligations')return `<div class="risk-table"><div class="risk-row head"><span>Item</span><span>Owner</span><span>Priority</span></div>${[['Migration window','Joint','High'],['Application dependency inventory','Customer','High'],['Site readiness confirmation','PTCL + Customer','Medium'],['SLA acceptance criteria','Joint','Medium']].map(([a,b,c])=>`<div class="risk-row"><span><b>${a}</b></span><span>${b}</span><span class="risk ${c.toLowerCase()}">${c}</span></div>`).join('')}</div>`;return `<div class="action-plan"><div><span>1</span><p><b>Validate the current-state inventory</b>Confirm sites, circuits, applications and business criticality.</p></div><div><span>2</span><p><b>Agree the target service levels</b>Set availability, response and recovery objectives.</p></div><div><span>3</span><p><b>Approve the pilot scope</b>Select representative sites and define success criteria.</p></div><div><span>4</span><p><b>Schedule the executive review</b>Resolve open commercial and governance decisions.</p></div></div>`}
function documents(){const isCustom=!!docFile;return `${title('DOCUMENT INTELLIGENCE','Turn documents into decisions.','Review contracts, proposals and reports with a structured workspace for summaries, risks, obligations and next steps.')}<section class="document-command"><div class="panel upload-panel"><div class="panel-title-row"><div><span class="section-kicker">ADD A DOCUMENT</span><h2>Start with a file or guided document</h2></div><span class="secure-note">${icon('shield')} Local file validation</span></div><div class="dropzone ${isCustom?'has-file':''}" data-drop="document"><span class="upload-cloud">${isCustom?icon('file'):icon('upload')}</span><h3>${isCustom?esc(docFile.name):'Drop a business document here'}</h3><p>${isCustom?'Ready in your document workspace':'PDF, DOCX, PPTX, XLSX, TXT or Markdown - up to 50 MB'}</p><div class="upload-cta-row"><button class="primary" data-action="choose-document">${icon('folder')} ${isCustom?'Replace file':'Choose from device'}</button><button class="outline" data-action="use-sample-doc">${icon('spark')} Open guided document</button></div></div><div class="upload-sources"><button data-action="cloud-source" data-source="Google Drive"><span class="provider drive">G</span><span><b>Google Drive</b><small>Connect source</small></span></button><button data-action="cloud-source" data-source="OneDrive"><span class="provider onedrive">${icon('cloud')}</span><span><b>OneDrive</b><small>Connect source</small></span></button><button data-action="cloud-source" data-source="SharePoint"><span class="provider sharepoint">S</span><span><b>SharePoint</b><small>Connect source</small></span></button></div><div class="document-queue"><div class="panel-title-row compact"><h3>Workspace document</h3>${isCustom?'<button data-action="clear-document">Remove</button>':'<span class="demo-badge">Guided document</span>'}</div><div class="document-row"><span class="pdf-icon">${isCustom?esc(docFile.name.split('.').pop().toUpperCase().slice(0,4)):'PDF'}</span><div><b>${isCustom?esc(docFile.name):'PTCL_Enterprise_Proposal.pdf'}</b><small>${isCustom?(docFile.size/1048576).toFixed(2)+' MB - Added just now':'18 pages - 2,304 words - Updated 2 hours ago'}</small></div><span class="status">${icon('check')}${isCustom?'Ready':'Analyzed'}</span></div></div></div><div class="document-results"><section class="panel intelligence-panel"><div class="document-context"><span class="summary-file">${icon('file')}</span><div><small>${isCustom?'YOUR DOCUMENT':'GUIDED DOCUMENT'}</small><h2>${isCustom?esc(docFile.name):'Enterprise Network Transformation Proposal'}</h2><p>${isCustom?'Awaiting selected analysis action':'Commercial proposal - Enterprise connectivity - Version 3.1'}</p></div><div class="document-score"><b>${isCustom?'Ready':'92%'}</b><span>${isCustom?'Validated':'Information coverage'}</span></div></div><div class="tabs document-tabs" role="tablist" aria-label="Document intelligence">${['Summary','Key Points','Risks & Obligations','Actions'].map(t=>`<button role="tab" aria-selected="${docTab===t}" class="${docTab===t?'active':''}" data-action="doc-tab" data-tab="${t}">${t}</button>`).join('')}</div><div class="document-insight-body">${documentInsightContent()}</div><div class="document-insight-footer"><span>${icon('history')} ${isCustom?'Added just now':'Analyzed in 12 seconds'}</span><span>${icon('shield')} ${isCustom?'Local file':'4 obligations identified'}</span><button class="outline" data-action="export-brief">${icon('download')} Export brief</button></div></section><section class="document-actions-panel"><div class="section-row"><div><span class="section-kicker">SMART ACTIONS</span><h2>Move the work forward</h2></div><span>Uses current document context</span></div><div class="document-action-cards">${[['file','Executive brief','Create a one-page leadership summary.'],['shield','Review obligations','Organize commitments, owners and dates.'],['grid','Compare versions','See what changed between two documents.'],['chat','Ask this document','Open a focused conversation with citations.']].map(([i,t,d])=>`<button data-action="document-action" data-title="${t}"><span class="mini-icon">${icon(i)}</span><span><b>${t}</b><small>${d}</small></span>${icon('chevron')}</button>`).join('')}</div></section></div></section>`}
function imageProfile(){const profiles={infrastructure:{label:'Infrastructure site',title:'Telecommunications infrastructure identified',summary:'The image shows a managed enterprise campus environment with network infrastructure, controlled access and visible supporting facilities.',confidence:'94%',objects:['Office campus','Network facility','Road access','Utility structures','Landscaping'],ocr:'PTCL',observations:['The primary facility appears operational and maintained.','Road access supports service and maintenance activity.','Visible infrastructure is consistent with an enterprise connectivity site.'],actions:['Create a site inventory record','Review physical access controls','Link the site to its service topology']},campus:{label:'Enterprise campus',title:'Connected business campus identified',summary:'A modern enterprise campus is shown against the Islamabad landscape, combining business facilities with communications infrastructure.',confidence:'96%',objects:['Commercial building','PTCL signage','Vehicles','Roadway','Mountain range'],ocr:'ptcl',observations:['Brand signage is clearly visible on the main building.','The campus has multiple road approaches and landscaped zones.','The setting suggests a major business or operations facility.'],actions:['Prepare a campus overview','Catalog visible facilities','Add to corporate location library']},screenshot:{label:'Business interface',title:'Enterprise application screen identified',summary:'The screenshot contains a structured business dashboard with navigation, search, workflow cards and account controls.',confidence:'91%',objects:['Navigation sidebar','Search field','Workflow cards','User profile','Action buttons'],ocr:'Home - AI Assistant - Document Insight - Image Analysis',observations:['Primary tasks are grouped into clear workflow cards.','The interface uses a consistent green enterprise design system.','Navigation separates creation, analysis and history functions.'],actions:['Extract all visible interface text','Review information hierarchy','Generate a usability checklist']},diagram:{label:'Architecture diagram',title:'CloudCore workflow diagram identified',summary:'The diagram maps CloudCore AI to document, assistant and image workspaces, with PTCL Smart Cloud as the underlying platform.',confidence:'98%',objects:['CloudCore AI node','Document workflow','AI Assistant','Image workflow','Platform layer'],ocr:'CloudCore AI - Documents - AI Assistant - Images - PTCL Smart Cloud',observations:['Three user workflows connect to a central AI capability.','The platform layer supports every workflow.','The diagram expresses a hub-and-spoke information flow.'],actions:['Convert to an implementation plan','Generate architecture notes','Identify integration boundaries']},custom:{label:'Uploaded image',title:'Image ready for secure analysis',summary:'Your image passed the local type and size checks and is ready for object, text, context and technical analysis.',confidence:'Ready',objects:['Pending analysis'],ocr:'Run OCR to extract text',observations:['The original image remains available in this browser session.','Choose a focused action to define the output you need.'],actions:['Identify visible objects','Extract text with OCR','Create a technical review']}};return profiles[activeImageExample]||profiles.custom}
function imageSource(){if(imageURL)return imageURL;if(activeImageExample==='screenshot')return 'assets/reference-home.png';if(activeImageExample==='diagram')return 'assets/diagram.svg';return 'assets/hero.png'}
function images(){const p=imageProfile(),src=imageSource();return `${title('VISUAL INTELLIGENCE','See more than what is visible.','Inspect infrastructure, screenshots, diagrams and business imagery with structured visual intelligence.')}<section class="vision-layout"><div class="vision-source"><section class="panel image-workbench"><div class="tabs image-tabs" role="tablist" aria-label="Image source"><button role="tab" aria-selected="${imageMode==='upload'}" class="${imageMode==='upload'?'active':''}" data-action="image-mode" data-mode="upload">${icon('upload')}Upload image</button><button role="tab" aria-selected="${imageMode==='url'}" class="${imageMode==='url'?'active':''}" data-action="image-mode" data-mode="url">${icon('link')}Use image URL</button></div>${imageMode==='upload'?`<div class="vision-preview" data-drop="image"><img src="${esc(src)}" alt="${esc(p.label)} analysis source"><div class="vision-overlay"><span>${icon('spark')} ${p.label}</span><button data-action="choose-image">${icon('upload')} Replace image</button></div><i class="scan-line"></i></div>`:`<form id="url-form" class="url-form"><span class="feature-icon">${icon('link')}</span><h3>Analyze an image from the web</h3><p>Paste a direct HTTPS link to a JPG, PNG or WEBP image.</p><input name="url" type="url" placeholder="https://example.com/image.jpg" aria-label="Image URL" required><button class="primary" type="submit">Load image ${icon('arrow')}</button></form>`}<div class="source-specs"><span>${icon('image')} JPG, PNG, WEBP</span><span>${icon('shield')} 20 MB maximum</span><span>${icon('check')} Local validation</span></div></section><section class="panel visual-library"><div class="section-row"><div><span class="section-kicker">GUIDED SOURCES</span><h2>Explore different image types</h2></div><span>4 scenarios</span></div><div class="visual-samples">${[['campus','building','Enterprise campus'],['screenshot','image','Application screen'],['infrastructure','signal','Infrastructure site'],['diagram','grid','Architecture diagram']].map(([id,i,t])=>`<button class="${activeImageExample===id?'active':''}" data-action="example-image" data-example="${id}"><span>${icon(i)}</span><b>${t}</b><small>${id==='screenshot'?'Interface and content':id==='diagram'?'Flows and components':id==='campus'?'Facilities and context':'Equipment and environment'}</small></button>`).join('')}</div></section></div><div class="vision-results"><section class="panel analysis-report"><div class="analysis-report-head"><span class="feature-icon">${icon('spark')}</span><div><span class="section-kicker">ANALYSIS REPORT</span><h2>${p.title}</h2><p>${p.summary}</p></div><div class="confidence-ring"><b>${p.confidence}</b><span>${p.confidence==='Ready'?'Status':'Confidence'}</span></div></div><div class="analysis-section"><div class="analysis-section-title"><h3>Detected elements</h3><span>${p.objects.length} items</span></div><div class="object-tags">${p.objects.map(o=>`<span>${icon('box')}${o}</span>`).join('')}</div></div><div class="analysis-columns"><div class="analysis-section"><div class="analysis-section-title"><h3>Extracted text</h3><span>OCR</span></div><blockquote>${p.ocr}</blockquote></div><div class="analysis-section"><div class="analysis-section-title"><h3>Technical observations</h3><span>Context</span></div><ul class="observation-list">${p.observations.map(o=>`<li>${icon('check')}${o}</li>`).join('')}</ul></div></div></section><section class="panel vision-actions"><div class="section-row"><div><span class="section-kicker">NEXT BEST ACTIONS</span><h2>Turn insight into work</h2></div><button data-action="export-image-report">Export report</button></div><div class="next-action-list">${p.actions.map((a,i)=>`<button data-action="image-action" data-title="${a}"><span>0${i+1}</span><b>${a}</b>${icon('arrow')}</button>`).join('')}</div></section></div></section>`}
function assistant(){const modes=[['Business Advisor','spark','Decisions and recommendations'],['Proposal Writer','file','Structured business writing'],['Service Support','settings','Troubleshooting and next steps']];return `${title('AI ASSISTANT','A focused partner for business work.','Choose how you want CloudCore AI to think, then bring a question, document or image into the conversation.')}<div class="assistant-modebar"><span>Working mode</span><div>${modes.map(([m,i,d])=>`<button class="${assistantMode===m?'active':''}" data-action="assistant-mode" data-mode="${m}">${icon(i)}<span><b>${m}</b><small>${d}</small></span></button>`).join('')}</div></div><section class="assistant-layout"><div class="chat-panel panel"><div class="chat-top">${mark('chat-brand-mark')}<div><strong>CloudCore AI</strong><small>${assistantMode}</small></div><span class="assistant-status"><i></i> Ready</span><button class="icon-button" data-action="new-chat" aria-label="Start new chat">${icon('plus')}</button></div><div class="messages" aria-live="polite">${messages.length?messages.map(m=>`<div class="message ${m.role}"><span class="message-avatar">${m.role==='user'?'A':mark('message-mark')}</span><div><p>${esc(m.content).replace(/\n/g,'<br>')}</p>${m.sources?.length?`<div class="message-sources">${m.sources.map(s=>`<span>${icon('file')}${esc(s)}</span>`).join('')}</div>`:''}</div></div>`).join(''):`<div class="chat-welcome">${mark('assistant-welcome-mark')}<span class="section-kicker">${assistantMode.toUpperCase()}</span><h2>${assistantMode==='Proposal Writer'?'What are we preparing?':assistantMode==='Service Support'?'What needs attention?':'What decision are you working through?'}</h2><p>${assistantMode==='Proposal Writer'?'Turn a rough brief into a clear, structured business document.':assistantMode==='Service Support'?'Describe the service, impact and what you have already checked.':'Bring the context, constraints and outcome you need.'}</p><div class="chat-starters">${(assistantMode==='Proposal Writer'?['Draft an executive proposal','Write a solution overview','Create a client follow-up','Turn notes into an email']:assistantMode==='Service Support'?['Internet service is unstable','Help diagnose high latency','Prepare an incident update','Plan a support escalation']:['Compare cloud deployment options','Recommend connectivity for 20 sites','Build a cyber security roadmap','Prepare discovery questions']).map(t=>`<button data-action="suggestion" data-prompt="${t}">${t}${icon('arrow')}</button>`).join('')}</div></div>`}</div>${composer('chat')}<div class="composer-meta"><span>${icon('shield')} Enterprise-ready workspace</span><span>Check critical decisions before action</span></div></div><aside class="assistant-context"><section class="panel context-card"><div class="section-row"><div><span class="section-kicker">CONVERSATION CONTEXT</span><h2>What CloudCore AI can use</h2></div></div><div class="context-items"><button data-action="attach-document"><span class="mini-icon">${icon('file')}</span><span><b>Document</b><small>${docFile?esc(docFile.name):'Add a proposal, contract or report'}</small></span>${docFile?icon('check'):icon('plus')}</button><button data-action="attach-image"><span class="mini-icon">${icon('image')}</span><span><b>Image</b><small>${imageFile?esc(imageFile.name):'Add a screenshot or site image'}</small></span>${imageFile?icon('check'):icon('plus')}</button><a href="#solutions"><span class="mini-icon">${icon('grid')}</span><span><b>Solution catalog</b><small>Six PTCL business solution areas</small></span>${icon('chevron')}</a></div></section><section class="panel answer-standard"><span class="section-kicker">ANSWER STANDARD</span><h2>Built for useful output</h2><div><span>${icon('check')}<b>Structured</b><small>Clear recommendation, rationale and next steps</small></span><span>${icon('check')}<b>Grounded</b><small>Uses the context available in this workspace</small></span><span>${icon('check')}<b>Actionable</b><small>Separates decisions, owners and follow-ups</small></span></div></section></aside></section>`}
function history(){let filtered=chats.filter(c=>c.title.toLowerCase().includes(historySearch.toLowerCase()));if(historyFilter==='Guided')filtered=filtered.filter(c=>c.sample);if(historyFilter==='Mine')filtered=filtered.filter(c=>!c.sample);const mine=chats.filter(c=>!c.sample).length,guided=chats.filter(c=>c.sample).length;return `${title('CONVERSATION LIBRARY','Your work, ready to continue.','Search, reopen and manage conversations saved in this browser. Guided examples remain clearly identified.')}<section class="history-summary"><article><span class="kpi-icon">${icon('chat')}</span><div><small>All conversations</small><strong>${chats.length}</strong><p>${mine} created by you</p></div></article><article><span class="kpi-icon">${icon('spark')}</span><div><small>Guided examples</small><strong>${guided}</strong><p>Ready to explore</p></div></article><article><span class="kpi-icon">${icon('history')}</span><div><small>Latest activity</small><strong>${chats.length?relativeTime(Math.max(...chats.map(c=>c.updated))):'--'}</strong><p>Stored on this device</p></div></article></section><section class="panel history-panel"><div class="history-toolbar"><label>${icon('search')}<input id="history-search" aria-label="Search conversations" placeholder="Search by topic or keyword..." value="${esc(historySearch)}"></label><div class="history-filters">${['All','Mine','Guided'].map(f=>`<button class="${historyFilter===f?'active':''}" data-action="history-filter" data-filter="${f}">${f}</button>`).join('')}</div><button class="primary" data-action="new-chat">${icon('plus')}New Chat</button></div><div class="history-table-head"><span>Conversation</span><span>Type</span><span>Updated</span><span></span></div><div id="history-list" class="history-list">${filtered.length?filtered.map(c=>{const last=[...c.messages].reverse().find(m=>m.role==='assistant');return `<div class="history-row"><span class="mini-icon">${icon(c.sample?'spark':'chat')}</span><button class="history-open" data-action="open-chat" data-id="${c.id}"><b>${esc(c.title)}</b><p>${esc(last?.content||'Conversation ready to continue').slice(0,125)}</p></button><span class="history-type ${c.sample?'guided':'mine'}">${c.sample?'Guided':'My conversation'}</span><span class="history-date">${relativeTime(c.updated)}<small>${c.messages.filter(m=>m.role==='user').length} prompts</small></span><button class="icon-button" data-action="delete-chat" data-id="${c.id}" aria-label="Delete conversation">${icon('trash')}</button></div>`}).join(''):`<div class="history-empty"><span class="feature-icon">${icon('search')}</span><h2>No conversations match</h2><p>Change the filter or start a focused conversation with CloudCore AI.</p><button class="outline" data-action="new-chat">Start a new chat ${icon('arrow')}</button></div>`}</div></section><section class="history-privacy"><span>${icon('shield')}</span><div><b>Your conversation library is device-local</b><p>Removing a conversation deletes it from this browser. Enterprise sync can be connected later.</p></div><button data-action="settings">Review settings</button></section>`}
function modal(content){$('#dialog-content').innerHTML=content;$('#dialog').showModal();bindDialog()}
function saveChats(){try{localStorage.setItem('cloudcore-chats',JSON.stringify(chats))}catch{toast('Your browser could not save chat history.')}}
function advisorResponse(t){const q=t.toLowerCase();if(assistantMode==='Proposal Writer')return {content:'Recommended structure:\n1. Executive context - define the business situation and desired outcome.\n2. Proposed solution - connect capabilities directly to the requirement.\n3. Delivery approach - set phases, responsibilities and dependencies.\n4. Service commitments - state availability, support and governance.\n5. Commercial next step - identify assumptions and the decision required.\n\nShare the audience, scope, timeline and constraints and I can turn this into a sharper first draft.',sources:['Proposal framework','PTCL solution catalog']};if(assistantMode==='Service Support')return {content:'Start with impact and scope. Confirm which users or sites are affected, when the issue began, whether the service is fully unavailable or degraded, and what changed recently. Then capture latency or error evidence, test an alternate path if available, and prepare the service ID for escalation.\n\nNext step: tell me the affected service, locations and current symptoms so I can build a focused diagnostic checklist.',sources:['Service triage playbook']};if(/document|pdf|summar|contract|proposal/.test(q))return {content:'Use Document Insight to separate the material into four decision layers: executive summary, key facts, risks and obligations, and an action plan. For a proposal, pay special attention to scope boundaries, customer dependencies, SLA language, acceptance criteria and commercial assumptions.',sources:['Document Insight framework']};if(/image|picture|diagram|screenshot|site/.test(q))return {content:'Use Image Analysis to identify visible objects, extract text, understand business context and turn findings into next actions. For infrastructure images, capture equipment, access conditions and site context. For screenshots, focus on content hierarchy, errors, states and user actions.',sources:['Visual Intelligence framework']};if(/cloud|solution|connect|security|wan|internet/.test(q))return {content:'A strong starting point is to define the workload and site profile first, then compare connectivity, cloud placement, security controls and operational ownership together. For a multi-site business, managed SD-WAN plus local cloud and managed security usually creates a balanced foundation. Validate data residency, recovery targets and support ownership before selecting the final design.',sources:['Business Solutions catalog','Enterprise architecture checklist']};return {content:'I would frame this as a business decision: clarify the outcome, list the constraints, compare realistic options, and identify the next reversible step. Share who the decision is for, the timeline, budget or policy limits, and what success looks like. I will return a recommendation with rationale, risks and a practical action plan.',sources:['CloudCore decision framework']}}
function sendMessage(t){t=t.trim();if(!t)return;messages.push({role:'user',content:t});const response=advisorResponse(t);messages.push({role:'assistant',content:response.content,sources:response.sources});if(!currentChat)currentChat=String(Date.now());const first=messages.find(m=>m.role==='user');const data={id:currentChat,title:first.content.slice(0,90),updated:Date.now(),mode:assistantMode,messages:[...messages]};chats=[data,...chats.filter(c=>c.id!==currentChat)];saveChats();if(location.hash==='#assistant'){route();const box=$('.messages');if(box)box.scrollTop=box.scrollHeight}else location.hash='assistant'}
function selectDocument(file){if(!file)return;if(!/\.(pdf|docx|pptx|xlsx|txt|md)$/i.test(file.name))return toast('Choose a PDF, DOCX, PPTX, XLSX, TXT or Markdown file.');if(file.size>50*1048576)return toast('Choose a document smaller than 50 MB.');docFile=file;docTab='Summary';location.hash='documents';route();toast('Document added to the workspace.')}
function selectImage(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type))return toast('Choose a JPG, PNG or WEBP image.');if(file.size>20*1048576)return toast('Choose an image smaller than 20 MB.');if(imageURL.startsWith('blob:'))URL.revokeObjectURL(imageURL);imageFile=file;imageURL=URL.createObjectURL(file);activeImageExample='custom';imageMode='upload';location.hash='images';route();toast('Image added to Visual Intelligence.')}
function downloadText(filename,text){const blob=new Blob([text],{type:'text/plain'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url)}
function solutionModal(s){return `<div class="modal-hero"><span class="feature-icon">${icon(s.icon)}</span><span class="solution-category">${s.category}</span><h2>${s.title}</h2><p>${s.desc}</p></div><div class="modal-grid"><div><h3>Core capabilities</h3><ul class="check-list">${s.bullets.map(b=>`<li>${icon('check')}${b}</li>`).join('')}</ul></div><div><h3>Designed for</h3><p>${s.fit}</p><h3>Primary value</h3><p>${s.metric}</p></div></div><div class="engagement-steps"><h3>A practical path forward</h3><div><span>1</span><p><b>Discover</b>Confirm users, sites, workloads and constraints.</p></div><div><span>2</span><p><b>Design</b>Map the service architecture and ownership model.</p></div><div><span>3</span><p><b>Deliver</b>Pilot, validate and scale with managed operations.</p></div></div><div class="dialog-actions"><button class="outline" data-action="add-solution-context" data-id="${s.id}">Ask AI about this</button><button class="primary" data-action="close-dialog">Done</button></div>`}
function compareModal(){const selected=solutionCompare.map(id=>solutionsData.find(s=>s.id===id));return `<h2>Solution comparison</h2><p>Compare the selected capabilities across intended fit, primary value and included services.</p><div class="comparison-table"><div class="comparison-row head"><span>Solution</span><span>Best for</span><span>Key value</span></div>${selected.map(s=>`<div class="comparison-row"><span><b>${s.title}</b><small>${s.category}</small></span><span>${s.fit}</span><span>${s.metric}</span></div>`).join('')}</div><h3>Recommended decision criteria</h3><ul><li>Business criticality and availability target</li><li>Data residency, latency and security requirements</li><li>Internal skills versus managed-service ownership</li><li>Deployment sequence and integration dependencies</li></ul><div class="dialog-actions"><button class="outline" data-action="add-comparison-context">Discuss with AI</button><button class="primary" data-action="close-dialog">Done</button></div>`}
function actions(a,el){if(a==='new-chat'){messages=[];currentChat=null;location.hash='assistant';route()}else if(a==='suggestion')sendMessage(el.dataset.prompt);else if(a==='assistant-mode'){assistantMode=el.dataset.mode;route()}else if(a==='choose-document'||a==='attach-document')$('#document-input').click();else if(a==='choose-image'||a==='attach-image')$('#image-input').click();else if(a==='doc-tab'){docTab=el.dataset.tab;route()}else if(a==='use-sample-doc'){docFile=null;docTab='Summary';route();toast('Guided proposal opened.')}else if(a==='clear-document'){docFile=null;docTab='Summary';route();toast('Document removed from this browser session.')}else if(a==='export-brief'){const name=docFile?docFile.name:'PTCL Enterprise Proposal';downloadText('cloudcore-document-brief.txt','CLOUDCORE AI DOCUMENT BRIEF\n\nDocument: '+name+'\n\n'+sampleSummary+'\n\nKey decisions:\n- Confirm rollout sequence\n- Agree service levels\n- Validate dependencies\n- Approve pilot scope');toast('Document brief downloaded.')}else if(a==='document-action'){const t=el.dataset.title;if(t==='Ask this document'){assistantMode='Business Advisor';sendMessage('Help me review '+(docFile?docFile.name:'the enterprise network transformation proposal')+' and identify the key decisions.')}else modal(`<span class="feature-icon">${icon('file')}</span><h2>${esc(t)}</h2><p>This action uses the current document context and organizes the output for a business review.</p><div class="modal-action-preview"><span>${icon('check')} Clear scope and purpose</span><span>${icon('check')} Evidence linked to the source document</span><span>${icon('check')} Owners, decisions and next actions separated</span></div><div class="dialog-actions"><button class="outline" data-action="close-dialog">Close</button><button class="primary" data-action="add-document-context">Continue in AI Assistant</button></div>`)}else if(a==='image-mode'){imageMode=el.dataset.mode;route()}else if(a==='example-image'){imageFile=null;imageURL='';activeImageExample=el.dataset.example;imageMode='upload';route();toast('Visual analysis updated for '+imageProfile().label.toLowerCase()+'.')}else if(a==='image-action'){modal(`<span class="feature-icon">${icon('spark')}</span><h2>${esc(el.dataset.title)}</h2><p>CloudCore AI will use the current visual report as context and preserve the detected objects, text and technical observations.</p><div class="modal-action-preview"><span>${icon('check')} Analysis source: ${esc(imageProfile().label)}</span><span>${icon('check')} Confidence: ${imageProfile().confidence}</span><span>${icon('check')} ${imageProfile().objects.length} detected elements available</span></div><div class="dialog-actions"><button class="outline" data-action="close-dialog">Close</button><button class="primary" data-action="add-image-context">Continue in AI Assistant</button></div>`)}else if(a==='export-image-report'){const p=imageProfile();downloadText('cloudcore-image-report.txt','CLOUDCORE AI VISUAL REPORT\n\n'+p.title+'\n\n'+p.summary+'\n\nDetected elements:\n- '+p.objects.join('\n- ')+'\n\nObservations:\n- '+p.observations.join('\n- '));toast('Visual report downloaded.')}else if(a==='solution-filter'){solutionFilter=el.dataset.filter;route()}else if(a==='solution-detail'){modal(solutionModal(solutionsData.find(s=>s.id===el.dataset.id)))}else if(a==='toggle-compare'){const id=el.dataset.id;if(solutionCompare.includes(id))solutionCompare=solutionCompare.filter(x=>x!==id);else if(solutionCompare.length<3)solutionCompare.push(id);else return toast('Choose up to three solutions to compare.');route()}else if(a==='compare-solutions')modal(compareModal());else if(a==='add-solution-context'){const s=solutionsData.find(x=>x.id===el.dataset.id);$('#dialog').close();assistantMode='Business Advisor';sendMessage('Help me evaluate '+s.title+' for my organization.')}else if(a==='add-comparison-context'){$('#dialog').close();assistantMode='Business Advisor';sendMessage('Compare '+solutionCompare.map(id=>solutionsData.find(s=>s.id===id).title).join(', ')+' and recommend selection criteria.')}else if(a==='add-document-context'){$('#dialog').close();sendMessage('Help me turn the current document analysis into an executive action plan.')}else if(a==='add-image-context'){$('#dialog').close();sendMessage('Use the current '+imageProfile().label+' visual report and prepare the next actions.')}else if(a==='history-filter'){historyFilter=el.dataset.filter;route()}else if(a==='cloud-source')modal(`<span class="feature-icon">${icon('cloud')}</span><h2>Connect ${esc(el.dataset.source)}</h2><p>Bring governed business files into Document Insight while keeping source permissions and file ownership intact.</p><div class="modal-action-preview"><span>${icon('shield')} Respect existing access controls</span><span>${icon('history')} Keep source version context</span><span>${icon('file')} Select only the files you need</span></div><div class="dialog-actions"><button class="outline" data-action="close-dialog">Not now</button><button class="primary" data-action="choose-document">Choose a local file</button></div>`);else if(a==='menu')$('.sidebar').classList.toggle('mobile-open');else if(a==='close-dialog')$('#dialog').close();else if(a==='open-chat'){const c=chats.find(c=>c.id===el.dataset.id);if(!c)return;messages=[...c.messages];currentChat=c.id;assistantMode=c.mode||'Business Advisor';location.hash='assistant'}else if(a==='delete-chat')modal(`<span class="feature-icon">${icon('trash')}</span><h2>Delete this conversation?</h2><p>This removes the conversation from this browser. The action cannot be undone from CloudCore AI.</p><div class="dialog-actions"><button class="outline" data-action="close-dialog">Cancel</button><button class="primary danger" data-action="confirm-delete" data-id="${el.dataset.id}">Delete conversation</button></div>`);else if(a==='confirm-delete'){chats=chats.filter(c=>c.id!==el.dataset.id);saveChats();$('#dialog').close();route();toast('Conversation deleted.')}else if(a==='settings')modal(`<h2>Workspace settings</h2><p>Review how this browser stores your work and how connected sources will behave.</p><div class="settings-list"><div>${icon('history')}<span><b>Conversation history</b><small>Saved in this browser so you can continue work.</small></span><span class="setting-state">On</span></div><div>${icon('shield')}<span><b>File handling</b><small>Local files are validated before a connected analysis service is used.</small></span><span class="setting-state">Local</span></div><div>${icon('cloud')}<span><b>Cloud sources</b><small>Google Drive, OneDrive and SharePoint are ready for account connection.</small></span><span class="setting-state neutral">Not connected</span></div></div>`);else if(a==='profile')modal(`<span class="avatar">A</span><h2>Ali's workspace</h2><p>CloudCore AI brings conversations, documents, images and business solutions into one focused workspace.</p><div class="profile-facts"><span><b>${chats.length}</b> conversations</span><span><b>${docFile?1:0}</b> documents</span><span><b>${imageFile?1:0}</b> images</span></div><a href="#landing" class="outline" data-action="close-dialog">Back to website</a>`);else if(a==='help')modal(`<h2>CloudCore AI help center</h2><p>Choose the workspace that matches the outcome you need.</p><div class="help-routes"><a href="#assistant">${icon('chat')}<span><b>AI Assistant</b><small>Ask, decide, draft and troubleshoot.</small></span></a><a href="#documents">${icon('file')}<span><b>Document Insight</b><small>Review summaries, risks and actions.</small></span></a><a href="#images">${icon('image')}<span><b>Image Analysis</b><small>Inspect objects, text and visual context.</small></span></a><a href="#solutions">${icon('grid')}<span><b>Business Solutions</b><small>Explore and compare PTCL capabilities.</small></span></a></div>`);else if(a==='solutions')location.hash='solutions'}
function bindDialog(){document.querySelectorAll('#dialog [data-action]').forEach(el=>el.onclick=()=>actions(el.dataset.action,el))}
const baseBind=bind;bind=function(){baseBind();document.querySelectorAll('.composer').forEach(f=>f.onsubmit=e=>{e.preventDefault();sendMessage(new FormData(f).get('prompt'))});if($('#search-form'))$('#search-form').onsubmit=e=>{e.preventDefault();const q=$('#search-form input').value.trim(),l=q.toLowerCase();const match=navs.find(n=>n[2].toLowerCase().includes(l));if(q&&match)location.hash=match[0];else if(q&&solutionsData.some(s=>s.title.toLowerCase().includes(l)||s.category.toLowerCase()===l)){solutionFilter='All';location.hash='solutions'}else if(q)sendMessage(q)};if($('#document-input'))$('#document-input').onchange=e=>selectDocument(e.target.files[0]);if($('#image-input'))$('#image-input').onchange=e=>selectImage(e.target.files[0]);document.querySelectorAll('[data-drop]').forEach(d=>{d.ondragover=e=>{e.preventDefault();d.classList.add('dragging')};d.ondragleave=()=>d.classList.remove('dragging');d.ondrop=e=>{e.preventDefault();d.classList.remove('dragging');(d.dataset.drop==='image'?selectImage:selectDocument)(e.dataTransfer.files[0])}});if($('#url-form'))$('#url-form').onsubmit=e=>{e.preventDefault();const url=new FormData(e.target).get('url');try{if(new URL(url).protocol!=='https:')throw Error()}catch{return toast('Enter a valid HTTPS image URL.')}const image=new Image();image.onload=()=>{imageFile=null;imageURL=url;activeImageExample='custom';imageMode='upload';route();toast('Image URL loaded into Visual Intelligence.')};image.onerror=()=>toast('The image could not be loaded. Check the direct image link.');image.src=url};if($('#history-search'))$('#history-search').oninput=e=>{historySearch=e.target.value;const start=e.target.selectionStart;route();$('#history-search').focus();$('#history-search').setSelectionRange(start,start)};if($('#dialog'))$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()}}
window.addEventListener('hashchange',route);route();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'navigate_cloudcore',title:'Open a CloudCore AI screen',description:'Navigate to a CloudCore AI frontend screen. Does not send messages or upload files.',inputSchema:{type:'object',properties:{screen:{type:'string',enum:['landing','home','assistant','documents','images','solutions','history']}},required:['screen'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['landing','home','assistant','documents','images','solutions','history'].includes(input.screen))throw new Error('Choose a supported CloudCore AI screen.');location.hash=input.screen;route();return{screen:input.screen,status:'opened'}}})).catch(()=>{})}catch{}}
